/bin/zsh -lc "env GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null /opt/homebrew/bin/python3 -c 'import json,itertools;from fractions import Fraction as F;from pathlib import Path;p=Path(\"evidence/markov-ca9709f2/stein-symbolic.json\");d=json.loads(p.read_text());out={}
for key in [\"shifted_mean\",\"shifted_bound\"]:
 q={tuple(k):F(v) for k,v in d[key]};squares=[];failed=[]
 for e in sorted([e for e,v in q.items() if v<0],reverse=True):
  v=-q[e];c=v/2;opts=[]
  for delta in itertools.product(range(-3,4),repeat=3):
   delta=delta+(0,);u=tuple(x+y for x,y in zip(e,delta));w=tuple(x-y for x,y in zip(e,delta))
   if u==w or min(u+w)<0:continue
   if q.get(u,0)>=c and q.get(w,0)>=c:opts.append((sum(abs(x) for x in delta),delta,u,w))
  if not opts:failed.append([e,str(q[e])]);continue
  _,delta,u,w=min(opts);q[u]-=c;q[w]-=c;q[e]=0;squares.append({\"coefficient\":str(c),\"center\":e,\"delta\":delta,\"common\":tuple(x-abs(y) for x,y in zip(e,delta)),\"positive_monomial\":tuple(max(x,0) for x in delta),\"negative_monomial\":tuple(max(-x,0) for x in delta)})
 out[key]={\"squares\":squares,\"failures\":failed,\"remaining\":[[k,str(v)] for k,v in q.items() if v]}
Path(\"evidence/markov-ca9709f2/stein-square-certificate.json\").write_text(json.dumps(out,indent=2)+\"\\n\");print(json.dumps({k:{\"squares\":len(v[\"squares\"]),\"failures\":v[\"failures\"]} for k,v in out.items()}))'"

/bin/zsh -lc "env GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null /opt/homebrew/bin/python3 -c 'import sys,json;sys.path.insert(0,\"research\");from stein_probe_ca9709f2 import solve,ev,O;fail=[];count=0
for r in [1000,10000,1000000]:
 for a in [2,10,100,r//100,r//10,r,10*r,100*r]:
  for m in [r,r+r//10,r+r//2,2*r-r//10,2*r-2]:
   H=3*a+r+4;n=m-r;L=2*r-m;C,P,ff=solve(a,m,r,H);b=L*ev(ff,n)-4*n*(a+r)*ev(P,n);v=2*C*(L+1)+b;count+=1
   if C<=0 or v<=0:fail.append({\"a\":a,\"r\":r,\"m\":m,\"C\":str(C),\"uniform\":str(v)})
out={\"cases\":count,\"failures\":fail,\"status\":\"finite exact auxiliary bound stress only\"};(O/\"stein-large-stress.json\").write_text(json.dumps(out,indent=2)+\"\\n\");print(json.dumps({\"cases\":count,\"failures\":len(fail),\"first\":fail[:3]}))'"
